values ('IELTS-M2', '1.1.0', '4c2820448c44d157f56a24ce79b9b14e78c4a0135e5516368d557ff18b156c0e', '11544d3c98d198f731b39a47c71d20397d35510f1964cedf515172c9c9ef624a', '{"code":"IELTS-M2","listening":{"parts":[{"groups":[{"form_title":"Riverside Hotel: room booking","instructions":"Complete the form below. Write ONE WORD AND/OR A NUMBER for each answer.","items":[{"n":1,"prompt":"Name: Daniel ______"},{"n":2,"prompt":"Date of party: ______ June"},{"n":3,"prompt":"Expected number of guests: about ______"},{"n":4,"prompt":"Room: the ______ Room"},{"n":5,"prompt":"Room cost with catering: £______"},{"n":6,"prompt":"Deposit: £______"}],"range":[1,6],"type":"completion","word_limit":2},{"form_title":"Party arrangements","instructions":"Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","items":[{"n":7,"prompt":"Buffet: £______ per person"},{"n":8,"prompt":"Own cake: tell the ______ in advance"},{"n":9,"prompt":"Music must finish by ______ pm"},{"n":10,"prompt":"Extra parking: public car park on ______ Street"}],"range":[7,10],"type":"completion","word_limit":2}],"part":1,"range":[1,10]},{"groups":[{"figure":{"alt":"Hilltop Community Park","note":"Fictional plan for practice.","src":"/ielts/mocks/IELTS-M2/listening-q11-15.png?v=4433c11dce28","title":"Hilltop Community Park"},"instructions":"Label the plan below. Write the correct letter, A–H, next to Questions 11–15.","items":[{"n":11,"prompt":"Visitor centre"},{"n":12,"prompt":"Community garden"},{"n":13,"prompt":"Children''s playground"},{"n":14,"prompt":"Café"},{"n":15,"prompt":"Toilets"}],"map":true,"options":["A","B","C","D","E","F","G","H"],"options_title":"Places","range":[11,15],"type":"matching"},{"instructions":"Choose the correct letter, A, B or C.","items":[{"n":16,"options":["A  near the lake.","B  in the field east of the garden.","C  on the main path."],"prompt":"Dogs can be let off the lead"},{"n":17,"options":["A  in the community garden.","B  in the café.","C  at the visitor centre."],"prompt":"Volunteers are most needed"},{"n":18,"options":["A  5 pm.","B  7 pm.","C  9 pm."],"prompt":"In winter, the park gates close at"},{"n":19,"options":["A  an evening concert.","B  a treasure hunt for children.","C  a boat race on the lake."],"prompt":"On the opening day, there will be"},{"n":20,"options":["A  the council.","B  local schools.","C  a vote of residents."],"prompt":"The park''s final name will be chosen by"}],"range":[16,20],"type":"mcq"}],"part":2,"range":[11,20]},{"groups":[{"instructions":"Choose the correct letter, A, B or C.","items":[{"n":21,"options":["A  Most shoppers do not notice them.","B  Shoppers mainly check them for new products.","C  Shoppers find the colours confusing."],"prompt":"What did Mei find surprising about traffic-light labels?"},{"n":22,"options":["A  do not use them regularly.","B  do not understand the colours.","C  do not trust the information."],"prompt":"According to Josh, the main problem with the labels is that people"},{"n":23,"options":["A  The figures are often wrong.","B  Products are sold in many sizes.","C  People eat different amounts."],"prompt":"Why does Josh think information per hundred grams can be misleading?"},{"n":24,"options":["A  by interviewing shoppers at the supermarket","B  through an online questionnaire","C  by speaking to students in the canteen"],"prompt":"How will the students collect data for their survey?"},{"n":25,"options":["A  7 minutes","B  15 minutes","C  20 minutes"],"prompt":"How long will the talk itself last?"}],"range":[21,25],"type":"mcq"},{"instructions":"Who will be responsible for each task? Write the correct letter, A, B or C, next to Questions 26–30.","items":[{"n":26,"prompt":"the introduction"},{"n":27,"prompt":"the slides"},{"n":28,"prompt":"the conclusion"},{"n":29,"prompt":"the handout"},{"n":30,"prompt":"booking a room for practice"}],"options":["A  Mei","B  Josh","C  both Mei and Josh"],"options_title":"People","range":[26,30],"type":"matching"}],"part":3,"range":[21,30]},{"groups":[{"form_title":"The honeybee waggle dance","instructions":"Complete the notes below. Write ONE WORD ONLY for each answer.","items":[{"n":31,"prompt":"Food is found by older workers known as ______."},{"n":32,"prompt":"Information must be shared quickly because flowers bloom and ______ quickly."},{"n":33,"prompt":"Von Frisch was awarded a ______ Prize for his research."},{"n":34,"prompt":"The dance takes place in the ______ on the comb."},{"n":35,"prompt":"The direction of the run is based on the position of the ______."},{"n":36,"prompt":"The length of the waggle run shows the ______ to the food."},{"n":37,"prompt":"When the food source is rich, the dancer ______ the dance more times."},{"n":38,"prompt":"The round dance is used for food within about 50 ______."},{"n":39,"prompt":"In the 2000s, ______ was used to follow individual bees."},{"n":40,"prompt":"Long journeys by city bees suggest that suitable flowers are ______."}],"range":[31,40],"type":"completion","word_limit":1}],"part":4,"range":[31,40]}]},"reading":{"passages":[{"groups":[{"instructions":"Do the following statements agree with the information given in Reading Passage 1? Write TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, or NOT GIVEN if there is no information on this.","items":[{"n":1,"prompt":"Growing plants without soil was first attempted in the last fifteen years."},{"n":2,"prompt":"The pinkish appearance of many indoor farms is the result of a deliberate choice about the light used."},{"n":3,"prompt":"Shoppers prefer the flavour of lettuce grown indoors to that of field-grown lettuce."},{"n":4,"prompt":"Retail businesses appreciate being able to rely on a steady supply throughout the year."},{"n":5,"prompt":"Indoor farming always has a smaller environmental impact than traditional agriculture."},{"n":6,"prompt":"Some vertical-farming businesses have failed because their expenses were too high."}],"range":[1,6],"type":"tfng"},{"form_title":"Vertical farming: key points","instructions":"Complete the table below. Choose ONE WORD ONLY from the passage for each answer.","items":[{"n":7,"prompt":"Lighting: modern lamps release relatively little ______, so they can be placed close to plants."},{"n":8,"prompt":"Pest control: ______ are seldom required inside sealed buildings."},{"n":9,"prompt":"Water: unused water is filtered and ______."},{"n":10,"prompt":"Main cost: electricity for ______."},{"n":11,"prompt":"Unsuitable crops: wheat and rice produce too much stalk and ______."},{"n":12,"prompt":"Research: breeding ______ plant varieties that fit between narrow shelves."},{"n":13,"prompt":"Research: siting farms near factories or data centres to use waste ______."}],"range":[7,13],"type":"completion","word_limit":1}],"labelled":false,"n":1,"paragraphs":["Inside a converted warehouse on the outskirts of a large city, lettuces are growing on shelves stacked almost to the ceiling. There is no soil, and not a single window admits daylight. Instead, the plants are illuminated by rows of purple-pink diodes, their roots suspended in trays through which a nutrient solution circulates continuously, while sensors record temperature, humidity and carbon dioxide levels every few seconds. Facilities of this kind, generally described as vertical farms, have multiplied rapidly over the past fifteen years, and their supporters claim that they could transform the way in which cities are supplied with fresh food.","The underlying idea is not entirely new. Growing plants without soil, a technique known as hydroponics, has been practised experimentally for well over a century, and commercial greenhouses have used it for decades. What distinguishes the modern vertical farm is the combination of hydroponics with complete control over the growing environment and with artificial lighting efficient enough to replace the sun altogether. The decisive technical development was the falling cost of light-emitting diodes, or LEDs, which convert electricity into light far more efficiently than earlier lamps and emit relatively little heat, so that they can be positioned only a few centimetres above the leaves without scorching them.","Because the environment is sealed, growers are able to adjust conditions to suit each crop precisely. The colour of the light, for example, can be tuned to the wavelengths that plants use most effectively for photosynthesis, which is why most facilities appear pink rather than white. Since pests have few opportunities to enter, pesticides are rarely necessary, and the produce frequently requires no washing before it is eaten. Most strikingly, the water that is not absorbed by the plants is collected, filtered and recirculated, so that a vertical farm may consume as little as five per cent of the water required to grow the same quantity of lettuce in an open field.","Advocates also emphasise the advantages of location. Conventional vegetables are frequently transported hundreds or even thousands of kilometres between farm and supermarket, losing freshness during the journey; a vertical farm, by contrast, can be situated within the city that it supplies, allowing produce to be harvested in the morning and sold the same afternoon. Furthermore, because harvests are unaffected by droughts, floods or unseasonal frosts, output remains consistent throughout the year, an attribute that retailers value highly.","The principal obstacle is energy. Sunlight is free, whereas electric lighting is not, and in most facilities lighting accounts for the largest single share of operating costs, followed by the climate-control systems that remove the heat and moisture generated inside the building. Unless that electricity is derived from renewable sources, the carbon emissions associated with a vertically farmed lettuce can actually exceed those of one grown outdoors and transported a considerable distance. Several well-funded companies have closed in recent years, having discovered that their running costs could not be recovered from the prices that consumers were prepared to pay. Critics also note that the buildings themselves, with their pumps, sensors and specialised equipment, represent a substantial initial investment that must be repaid before any profit is made.","For these reasons, the range of crops that can be grown profitably remains narrow. Leafy greens and herbs are well suited to vertical farming because they mature quickly, occupy little height and consist largely of edible material. Staple crops such as wheat and rice, in contrast, require extended growing periods and produce a high proportion of stalk and straw, which renders indoor cultivation economically unworkable at present. Even tomatoes and strawberries, which a number of companies are now attempting to cultivate, demand substantially more light and space than lettuce does.","Researchers are attempting to address these limitations in a variety of ways. Some are developing plant varieties specifically bred for indoor cultivation, compact enough to fit between closely spaced shelves and capable of growing well under lower light intensity. Others are investigating whether lighting could be concentrated in periods when electricity is cheapest, such as during the night, without reducing yields significantly. A third approach involves locating farms close to sources of waste heat, such as factories or data centres, so that energy which would otherwise be lost can contribute to maintaining suitable growing temperatures.","Whether vertical farms will ever become more than a specialised supplier of salad ingredients remains uncertain. They are unlikely to replace conventional agriculture, which still produces the overwhelming majority of the world''s calories. Nevertheless, in cities where land is scarce, the climate is harsh or fresh produce must otherwise be imported over long distances, they may come to occupy a valuable, if limited, place in the food supply, particularly if the cost of renewable electricity continues to decline."],"range":[1,13],"title":"Farming upwards: the rise of vertical farms"},{"groups":[{"instructions":"Reading Passage 2 has six paragraphs, A–F. Which paragraph contains the following information? Write the correct letter, A–F. NB You may use any letter more than once.","items":[{"n":14,"prompt":"an explanation of why the animals were commercially attractive"},{"n":15,"prompt":"a reference to human intervention to help the species spread"},{"n":16,"prompt":"a counter-argument to a complaint made by one group of workers"},{"n":17,"prompt":"a reason for uncertainty about an estimate"},{"n":18,"prompt":"an example of a change in the behaviour of a predator"}],"options":["A","B","C","D","E","F"],"options_title":"Paragraphs","range":[14,18],"type":"matching"},{"instructions":"Choose TWO letters, A–E.","options":["A  They reduce the impact of waves on the coast.","B  They provide food for sea otters.","C  They are harvested as a source of fertiliser.","D  They support many other kinds of marine life.","E  They attract visitors to coastal areas."],"range":[19,20],"stem":"Which TWO benefits of kelp forests are mentioned in the passage?","type":"multi"},{"instructions":"Choose TWO letters, A–E.","options":["A  pollution reaching the sea from the land","B  a shortage of sea urchins","C  illegal hunting for fur","D  rising sea temperatures","E  attacks by larger marine animals"],"range":[21,22],"stem":"Which TWO current threats to sea otters are mentioned in the passage?","type":"multi"},{"instructions":"Answer the questions below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the passage for each answer.","items":[{"n":23,"prompt":"In which year did an agreement end the commercial hunting of sea otters?"},{"n":24,"prompt":"What do sea otters have instead of a fat layer to keep them warm?"},{"n":25,"prompt":"What did kelp forests become in places where otters were absent?"},{"n":26,"prompt":"What term do ecologists use for an animal with an unusually large effect on its environment?"}],"range":[23,26],"type":"short","word_limit":3}],"labelled":true,"n":2,"paragraphs":["Along the Pacific coast of North America, the sea otter has staged one of the more remarkable recoveries in the history of wildlife conservation. Two centuries ago, several hundred thousand of these animals are thought to have inhabited the coastal waters in a broad arc stretching from northern Japan to the Baja California peninsula. Unlike most marine mammals, however, sea otters possess no insulating layer of blubber; instead, they rely on a coat of extraordinarily dense fur, with more hairs per square centimetre than any other mammal, which traps a layer of air against the skin. That same characteristic made their pelts exceptionally valuable to fur traders, and from the eighteenth century onwards they were hunted relentlessly. Historical records from trading companies suggest that tens of thousands of pelts were shipped across the Pacific in some years, a scale of exploitation that few populations of a slow-breeding mammal could withstand.","By the early twentieth century, the species had been reduced to perhaps one or two thousand individuals, scattered among a handful of isolated colonies, and many observers assumed that it was destined for extinction. International protection was finally agreed in 1911, when a treaty between several Pacific nations prohibited commercial hunting. Recovery, nonetheless, proceeded slowly. Sea otters reproduce at a modest rate, typically giving birth to a single pup at a time, and the surviving populations were too widely dispersed to recolonise their former range unaided. In several regions, conservationists eventually relocated animals by boat or aircraft in an effort to re-establish colonies on stretches of coast where the species had disappeared. Some of these translocations failed, as released animals dispersed far from the intended site or failed to survive the stress of capture and transport, but others established colonies that have since expanded steadily along the coast.","As numbers increased, scientists began to observe that the otters'' return was transforming entire coastal ecosystems. Sea otters consume large quantities of sea urchins, spiny animals that graze on kelp, the giant seaweed that forms dense underwater forests in cool, shallow waters. Where otters had been eliminated, urchin populations had multiplied unchecked and reduced extensive kelp forests to barren expanses of rock. Where otters were reintroduced, urchin numbers declined and the kelp regenerated, sometimes within a few years. Ecologists cite this sequence as a classic illustration of a ''keystone species'', an animal whose influence on its environment is disproportionate to its abundance. The phenomenon has been documented in Alaska, British Columbia and California, and although its details vary from site to site, the general pattern has proved remarkably consistent.","The recovery of the kelp has implications that extend beyond the otters themselves. Kelp forests provide shelter and nourishment for hundreds of other species, including commercially significant fish, and they dampen the force of waves approaching the shore. Kelp also absorbs carbon dioxide as it grows, and some researchers have estimated that the presence of otters may substantially increase the quantity of carbon stored along coastlines where they are found. These calculations remain controversial, however, because much depends on how long the carbon taken up by kelp remains locked away rather than being returned to the atmosphere. Some tourism operators, too, have begun to promote otter-watching excursions, although the economic value of such activities has not been systematically assessed. Even so, the broad ecological benefits of restored kelp forests are now widely accepted among marine biologists.","Not everyone has greeted the otters'' return enthusiastically. Shellfish fishermen, in particular, complain that the animals consume the clams, crabs and abalone on which their livelihoods depend, and in some areas the reappearance of otters has coincided with the collapse of local shellfish fisheries. Conservationists respond that these fisheries flourished in the first place largely because the otters had been removed, and that their productivity during the twentieth century was therefore an artificial situation rather than a natural one. Negotiating between these perspectives has become a recurrent source of tension in coastal communities. In parts of Alaska, indigenous communities have also raised the question of whether traditional, small-scale harvesting of otters should be permitted where populations have recovered strongly, a proposal that remains contentious.","Despite its successes, the sea otter remains vulnerable. Because the animals depend on their fur for warmth, contamination by oil prevents it from insulating them, and a single major spill can prove fatal to hundreds of individuals. Disease, frequently associated with pollutants and parasites carried into the sea by rivers and storm drains, has become a growing cause of mortality in certain populations. In some areas, increased predation by orcas, which appear to have turned to otters as their usual prey has declined, has caused sharp and unexpected falls in numbers. The species has therefore been described not as rescued but as recovering, a distinction that conservationists insist upon. Monitoring programmes now track the size and health of the main populations, providing early warning of declines that might otherwise go unnoticed until recovery has been reversed."],"range":[14,26],"title":"The return of the sea otter"},{"groups":[{"instructions":"Do the following statements agree with the claims of the writer in Reading Passage 3? Write YES if the statement agrees with the claims of the writer, NO if the statement contradicts the claims of the writer, or NOT GIVEN if it is impossible to say what the writer thinks about this.","items":[{"n":27,"prompt":"Emotional arguments in favour of handwriting are sufficient to justify the time spent on it."},{"n":28,"prompt":"Evidence from brain scans about handwriting should be interpreted carefully."},{"n":29,"prompt":"Later research has consistently confirmed the benefits of taking notes by hand."},{"n":30,"prompt":"Teachers generally prefer marking typed work to handwritten work."},{"n":31,"prompt":"Some students may lose marks in examinations because they write too slowly."},{"n":32,"prompt":"Children should be taught to join their letters rather than print them."}],"range":[27,32],"type":"ynng"},{"form_title":"Handwriting and learning","instructions":"Complete the summary below. Choose ONE WORD ONLY from the passage for each answer.","items":[{"n":33,"prompt":"Young children who learn letters by hand later ______ them more easily than those who use a keyboard."},{"n":34,"prompt":"Writing a letter forces a child to pay close attention to its ______."},{"n":35,"prompt":"Because handwriting is slow, students must summarise and ______ instead of copying every word."},{"n":36,"prompt":"Pen and paper do not depend on a supply of ______ or an internet connection."}],"range":[33,36],"type":"completion","word_limit":1},{"instructions":"Choose the correct letter, A, B, C or D.","items":[{"n":37,"options":["A  has already been taken by most education systems.","B  is being made too hastily.","C  is mainly motivated by cost.","D  has been opposed by most parents."],"prompt":"In the first paragraph, the writer suggests that the decision to drop handwriting"},{"n":38,"options":["A  Its results may be explained by students'' habits with the device.","B  It proved that typing damages understanding.","C  It involved too few students to be useful.","D  It was designed to promote handwriting."],"prompt":"What does the writer say about the laptop experiment?"},{"n":39,"options":["A  took time away from typing practice.","B  focused on neatness rather than ease of writing.","C  were too difficult for young children.","D  discouraged students from expressing ideas."],"prompt":"The writer criticises traditional copying exercises because they"},{"n":40,"options":["A  Typing should replace handwriting in later school years.","B  Schools should teach both skills for their different strengths.","C  Handwriting is more important than typing for older students.","D  The evidence on handwriting is too weak to guide policy."],"prompt":"What is the writer''s main conclusion?"}],"range":[37,40],"type":"mcq"}],"labelled":false,"n":3,"paragraphs":["In classrooms across much of the world, the pencil is steadily yielding to the keyboard. Children who would once have devoted hours to practising joined-up script now learn to type during their earliest years at school, and a growing proportion of their written work is produced and submitted on screens. Several education systems have already removed cursive writing from the compulsory curriculum, and others are considering whether to follow. Since most adults now write far more on keyboards than by hand, it is tempting to conclude that handwriting has become an obsolete skill, retained largely out of nostalgia. I believe that conclusion is premature, although not for the reasons most commonly advanced by its opponents.","The case for handwriting is frequently presented in sentimental terms: a handwritten letter is said to be more personal, a signature an expression of individual character, and fine penmanship a mark of education and discipline. These arguments may possess a certain charm, but they cannot justify the considerable amount of classroom time that the teaching of handwriting requires. If the only advantages of writing by hand were aesthetic or emotional, schools would be entirely justified in concentrating their limited resources elsewhere. Indeed, by resting the case on such grounds, defenders of handwriting may inadvertently strengthen the position of those who regard it as an outdated accomplishment.","The more persuasive arguments concern learning rather than appearance. A number of studies have found that young children who practise forming letters by hand subsequently recognise them more readily than children who learn the same letters by selecting them on a keyboard. One plausible explanation is that drawing a letter obliges the child to attend to its shape in detail, whereas pressing a key requires only that the correct key be identified. Brain-imaging research has indicated that regions associated with reading become more active after handwriting practice than after typing practice, although such studies have generally involved small numbers of participants and their conclusions should be treated with appropriate caution.","Comparable claims have been made regarding older students. In one widely publicised experiment, university students who took lecture notes by hand performed better on conceptual questions about the lecture than those who typed their notes on laptops. The researchers attributed this to speed: because handwriting is slower, students are compelled to summarise and select rather than transcribe the lecturer''s words verbatim, and that process of selection deepens their understanding. Subsequent attempts to replicate the finding, however, have yielded inconsistent results, and it remains possible that the advantage reflects the way in which students choose to use a laptop rather than any inherent property of handwriting itself. It would be unwise, therefore, to treat this single study as decisive evidence that laptops should be banned from lecture theatres, as some enthusiastic commentators have proposed.","There are also practical considerations. In many countries, important examinations continue to be written on paper, and students whose handwriting is slow or illegible may be penalised not for their ideas but for their inability to record them quickly enough. Until such examinations are conducted entirely on computers, abandoning instruction in handwriting would place some students at a measurable disadvantage. It is worth noting, too, that a pen and paper require neither electricity nor an internet connection, a consideration of some significance in schools where access to technology remains unreliable. Teachers also report that students who cannot write fluently by hand often find it more difficult to annotate texts, sketch diagrams or jot down quick notes during discussions, activities that remain a routine part of classroom learning even in schools that are well equipped with computers.","Another consideration, rarely mentioned in public debate, concerns students with particular learning difficulties. For some children with conditions that affect fine motor control, the physical act of writing is so laborious that it obstructs the expression of their ideas, and for these students access to a keyboard can be genuinely liberating. Any sensible policy must therefore allow for flexibility, recognising that the arguments which apply to the majority of learners may not apply to every individual, and that teachers are generally best placed to judge which approach serves a particular child.","None of this suggests that schools should resist the teaching of typing, which is indisputably essential in modern working life. Nor does it require a return to the hours of copying exercises that were once commonplace, many of which were concerned more with uniformity of appearance than with fluency. The objective should be handwriting that is legible and sufficiently rapid to keep pace with thought, not handwriting that is beautiful. Whether that writing is joined or printed is, in my view, considerably less significant than whether the child can produce it comfortably and without conscious effort.","The most sensible approach, then, is not to choose between pen and keyboard but to determine what each does best. Handwriting appears particularly valuable in the early stages of literacy and when the aim is to think and remember, while typing is superior for producing, revising and sharing longer texts. A curriculum that allocates time to both, and that explains to students why each matters, is likely to serve them better than one that treats either skill as a relic or as a substitute for the other. Such a curriculum would also be easier to defend against the charge of nostalgia, since it rests on evidence about learning rather than on attachment to tradition."],"range":[27,40],"title":"Should schools still teach handwriting?"}]},"rights":"Original Brains Heist LLC practice test, AI-assisted. All people, places, organisations and data are fictional. Not official IELTS material and not endorsed by IELTS.","schema":"bh-ielts-mock-cbt/1","test_type":"Academic","title":"Mock Test 2","version":"1.1.0","writing":{"task1":{"figure":{"alt":"Two maps of Eastbridge town centre. In 2005, a main road crossed the centre from west to east, with a car park in the north-west, a bus station in the north-east, a row of shops along the south side of the road, a market square in the middle of the south, and a factory in the south-east by the river. Today, the main road through the centre is pedestrianised and traffic uses a new ring road to the north; the car park has become a park, the bus station has been replaced by a library, the shops remain, the market square has a new café, and the factory has been converted into apartments with a riverside walk.","note":"Fictional maps for practice.","src":"/ielts/mocks/IELTS-M2/writing-task1.png?v=4d35c8ba1e42","title":"Eastbridge town centre"},"minimum_words":150,"prompt":"The maps below show the centre of the town of Eastbridge in 2005 and today. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.","suggested_minutes":20},"task2":{"minimum_words":250,"prompt":"In many cities, traffic congestion is becoming worse every year. What are the main causes of this problem, and what measures could be taken to reduce it? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.","suggested_minutes":40}}}'::jsonb, '{"listening":{"1":{"a":["Fenwick"],"t":"completion","w":2},"10":{"a":["Bridge"],"t":"completion","w":2},"11":{"a":["A"],"t":"matching"},"12":{"a":["B"],"t":"matching"},"13":{"a":["H"],"t":"matching"},"14":{"a":["E"],"t":"matching"},"15":{"a":["G"],"t":"matching"},"16":{"a":["B"],"t":"mcq"},"17":{"a":["C"],"t":"mcq"},"18":{"a":["A"],"t":"mcq"},"19":{"a":["B"],"t":"mcq"},"2":{"a":["21","21st","twenty-first"],"t":"completion","w":2},"20":{"a":["C"],"t":"mcq"},"21":{"a":["B"],"t":"mcq"},"22":{"a":["A"],"t":"mcq"},"23":{"a":["C"],"t":"mcq"},"24":{"a":["B"],"t":"mcq"},"25":{"a":["B"],"t":"mcq"},"26":{"a":["B"],"t":"matching"},"27":{"a":["A"],"t":"matching"},"28":{"a":["C"],"t":"matching"},"29":{"a":["A"],"t":"matching"},"3":{"a":["50","fifty"],"t":"completion","w":2},"30":{"a":["B"],"t":"matching"},"31":{"a":["foragers"],"t":"completion","w":1},"32":{"a":["fade"],"t":"completion","w":1},"33":{"a":["Nobel"],"t":"completion","w":1},"34":{"a":["dark"],"t":"completion","w":1},"35":{"a":["sun"],"t":"completion","w":1},"36":{"a":["distance"],"t":"completion","w":1},"37":{"a":["repeats"],"t":"completion","w":1},"38":{"a":["metres","meters","m"],"t":"completion","w":1},"39":{"a":["radar"],"t":"completion","w":1},"4":{"a":["Garden"],"t":"completion","w":2},"40":{"a":["scarce"],"t":"completion","w":1},"5":{"a":["280","two hundred and eighty"],"t":"completion","w":2},"6":{"a":["100","one hundred","a hundred"],"t":"completion","w":2},"7":{"a":["22","twenty-two"],"t":"completion","w":2},"8":{"a":["kitchen"],"t":"completion","w":2},"9":{"a":["11","eleven","11.00","11:00"],"t":"completion","w":2}},"reading":{"1":{"a":["FALSE"],"t":"tfng"},"10":{"a":["lighting"],"t":"completion","w":1},"11":{"a":["st